package com.xenris.liquidwarsos;
public final class Continuous177Check {
 static int n;static void ok(boolean x,String why){n++;if(!x)throw new AssertionError(why);}
 static WorldCamera c(){WorldCamera c=new WorldCamera();c.viewport(2.2f);c.world(1600,960,54,0,false,800,480);return c;}
 static float run(int hz){WorldCamera c=c();short[] x=new short[5],y=new short[5];c.beginTouch(19);c.trackTouch(0,19,.9f,.5f);c.finishTouchTargets(1);c.touchTarget(c.mapX(.9f,1),c.mapY(.5f,1));float start=c.left;c.frame(1000000000L);for(int k=1;k<=hz;k++){c.frame(1000000000L+k*1000000000L/hz);if(c.fillTouchTargets(x,y))c.touchTarget(x[0],y[0]);ok(Math.abs(c.screenX(x[0],1000)-900)<=1.4f,"target remains at held finger");ok(Math.abs(c.bottom-298.18182f)<.1f,"horizontal hold no y drift");}ok(c.left>start+250,"stationary held finger pans every frame");short held=x[0];c.endTouch();for(int k=1;k<70;k++){c.frame(3000000000L+k*1000000000L/hz);ok(!c.fillTouchTargets(x,y),"release emits no automatic targets");}ok(x[0]==held,"release retains final destination");return c.left-start;}
 public static void main(String[] args){float a=run(30),b=run(60),d=run(120);ok(Math.abs(a-b)<1&&Math.abs(b-d)<1,"refresh independent pan");WorldCamera c=c();short[] xs=new short[5],ys=new short[5];int[] ids={0,3,7,11,19};for(int k=0;k<5;k++){c.beginTouch(ids[k]);c.trackTouch(k,ids[k],.6f+k*.05f,.4f+k*.03f);}c.finishTouchTargets(5);ok(c.fillTouchTargets(xs,ys),"all5 projected");for(int k=0;k<5;k++)ok(xs[k]==c.mapX(.6f+k*.05f,1),"IDs map by slot");c.endTouch();ok(!c.touching()&&!c.fillTouchTargets(xs,ys),"cancel and focus remove all held pointers");
 c=c();c.beginTouch(3);c.trackTouch(0,3,.5f,.5f);c.finishTouchTargets(1);c.frame(1000000000L);float lx=c.left,by=c.bottom;for(int k=1;k<500;k++)c.frame(1000000000L+k*8333333L);ok(c.left==lx&&c.bottom==by,"centre deadzone no rounding drift");
 c.endTouch();c.pan(200,200);ok(!c.fillTouchTargets(xs,ys),"minimap alone no movement command");c.beginTouch(11);c.trackTouch(0,11,.9f,.4f);c.touchTarget(500,250);ok(c.following,"main map hold resumes following after minimap pan");c.frame(7000000000L);c.frame(17000000000L);ok(c.left-lx<=800*.35f*.05f,"long frame bounded");c.endTouch();c.world(800,480,1,0,false,400,240);c.beginTouch(0);c.trackTouch(0,0,.9f,.2f);c.frame(18000000000L);c.frame(19000000000L);ok(c.left==0&&c.bottom==0&&!c.fillTouchTargets(xs,ys),"ordinary maps stay full view");System.out.println("PASS "+n+" continuous camera/5pointer/release/30-60-120Hz/lifecycle checks");}
}
